import{_ as o,C as s,o as n,c as l,a2 as t,E as a}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Account Health","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-account-health.md","filePath":"sellers/seller-account-health.md","lastUpdated":1789411447000}'),h={name:"sellers/seller-account-health.md"};function i(c,e,d,u,g,p){const r=s("ImagePopup");return n(),l("div",null,[e[0]||(e[0]=t('<h1 id="account-health" tabindex="-1">Account Health <a class="header-anchor" href="#account-health" aria-label="Permalink to &quot;Account Health&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>Account health shows how well a seller is serving customers, based on cancelled orders, customer ratings and reports. Sellers use it to spot problems early, and the admin uses it to find sellers who need attention.</p><h2 id="check-your-account-health" tabindex="-1">Check your account health <a class="header-anchor" href="#check-your-account-health" aria-label="Permalink to &quot;Check your account health&quot;">​</a></h2><p>Sellers go to <strong>Performance &gt;&gt; Account Health</strong> in the Seller Panel.</p>',5)),a(r,{src:"/images/seller-account-health/account-health.png",alt:"The Account Health page in the Seller Panel"}),e[1]||(e[1]=t('<p>The page shows:</p><ul><li><strong>Overall Health</strong> — <strong>Healthy</strong>, <strong>At Risk</strong> or <strong>Unhealthy</strong>. It follows the worst of the metrics below.</li><li><strong>Health Score</strong> — a score out of 100.</li><li><strong>Order Cancellation Rate</strong> — the share of your ordered items that were cancelled in the last 30 days, whether you, the customer or the admin cancelled them.</li><li><strong>Customer Feedback</strong> — your average rating from approved reviews of your shop in the last 90 days.</li><li><strong>Flags</strong> — reports raised against your shop by customers in the last 90 days. It appears when seller reporting is switched on.</li></ul><p>Each metric is marked <strong>Good</strong>, <strong>Needs Attention</strong> or <strong>Critical</strong>, or <strong>No Data</strong> when there is nothing to measure yet.</p><h3 id="refresh-the-figures" tabindex="-1">Refresh the figures <a class="header-anchor" href="#refresh-the-figures" aria-label="Permalink to &quot;Refresh the figures&quot;">​</a></h3><p>Click <strong>Refresh now</strong> to recalculate. You can refresh again after 60 minutes. Team members need the <strong>Refresh Account Health</strong> permission.</p><h3 id="see-how-the-score-is-worked-out" tabindex="-1">See how the score is worked out <a class="header-anchor" href="#see-how-the-score-is-worked-out" aria-label="Permalink to &quot;See how the score is worked out&quot;">​</a></h3><p>Click <strong>How is this calculated?</strong>. The guide explains each metric and has a live calculator where you can try different values. Nothing you enter is saved.</p>',7)),a(r,{src:"/images/seller-account-health/health-guide.png",alt:"The How the Health Score Is Calculated guide"}),e[2]||(e[2]=t('<h2 id="what-each-metric-needs" tabindex="-1">What each metric needs <a class="header-anchor" href="#what-each-metric-needs" aria-label="Permalink to &quot;What each metric needs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Good</th><th>Needs Attention</th><th>Critical</th></tr></thead><tbody><tr><td><strong>Order Cancellation Rate</strong></td><td>Below the warning rate</td><td>At or above the warning rate</td><td>Above the critical rate</td></tr><tr><td><strong>Customer Feedback</strong></td><td>4.0 or higher</td><td>3.0 to 3.9</td><td>Below 3.0</td></tr><tr><td><strong>Flags</strong></td><td>Well under the red flag limit</td><td>Approaching the limit</td><td>Close to or over the limit</td></tr></tbody></table><p>The warning and critical cancellation rates and the red flag limit are set by the admin in <a href="./../configuration/moderation-and-health">Moderation &amp; Health</a>.</p><h2 id="how-the-score-works" tabindex="-1">How the score works <a class="header-anchor" href="#how-the-score-works" aria-label="Permalink to &quot;How the score works&quot;">​</a></h2><ul><li>The 100 points are shared equally between the metrics that count: cancellations always, feedback once the seller has reviews, and flags when reporting is on.</li><li>A perfect metric earns its full share. A poor one takes points away.</li><li>A score of 67 to 100 is <strong>Healthy</strong>, 34 to 66 is <strong>At Risk</strong>, and 0 to 33 is <strong>Unhealthy</strong>.</li></ul><p>Because <strong>Overall Health</strong> follows the worst metric, a seller can have a high score and still be marked <strong>Unhealthy</strong> when one metric is critical.</p><h2 id="when-the-figures-change" tabindex="-1">When the figures change <a class="header-anchor" href="#when-the-figures-change" aria-label="Permalink to &quot;When the figures change&quot;">​</a></h2><p>Account health is stored when it is refreshed:</p><ul><li>the seller clicks <strong>Refresh now</strong>;</li><li>the admin clicks <strong>Refresh Account Health</strong> on the seller&#39;s row, or uses it as a bulk action.</li></ul><p>When subscription plans are on, every seller is also refreshed once a day by the store&#39;s scheduler. Until a seller is refreshed for the first time, the admin&#39;s list shows <strong>Not calculated</strong>.</p><h2 id="for-the-admin" tabindex="-1">For the admin <a class="header-anchor" href="#for-the-admin" aria-label="Permalink to &quot;For the admin&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Sellers</strong>. The <strong>Account Health</strong> column shows each seller&#39;s score and band, their cancellation rate, rating and flags.</p><ul><li>To find sellers who need attention, click <strong>Filter</strong> and choose <strong>Unhealthy</strong> or <strong>At Risk</strong> under <strong>Account Health</strong>.</li><li>To recalculate, click the <strong>Refresh Account Health</strong> icon on a row, or tick several sellers and use <strong>Select Action &gt;&gt; Refresh Account Health</strong>.</li></ul><p>The list shows the band of the score, so it can say <strong>Healthy</strong> while one of the seller&#39;s metrics is critical. Open the seller&#39;s Account Health page with <strong>Login as Seller</strong> to see each metric.</p><h2 id="keep-your-account-healthy" tabindex="-1">Keep your account healthy <a class="header-anchor" href="#keep-your-account-healthy" aria-label="Permalink to &quot;Keep your account healthy&quot;">​</a></h2><ul><li>Keep stock accurate so you don&#39;t have to cancel orders.</li><li>Describe products honestly so customers get what they expect.</li><li>Answer customer messages quickly and resolve returns fairly.</li><li>Read reviews and flags to see what customers are unhappy about.</li></ul>',16))])}const w=o(h,[["render",i]]);export{f as __pageData,w as default};
